AS
begin
  if (
      not(new.ES_UID is null) and
      not(new.es_odeslano is null) and
      not((new.datum=old.datum) and (new.cas=old.cas) and (new.casdo=old.casdo))
      )
  then begin
    /* smazat dosud neodeslane updaty */
    delete from ES_APPUPD where IDOBJ=new.idobj and TYP='U' and (ODESLANO is NULL);

    insert into ES_APPUPD(UID, IDPAC, IDPRAC, IDUZI, IDOBJ, DATUM, CAS, CASDO, TYP, IDCINNOSTI)
    values(new.es_uid, new.idpac, new.idprac, new.iduzi, new.idobj, new.datum, new.cas, new.casdo, 'U', new.idcinnosti);
  end

  /* odeslani requestu se nezdarilo vynulujeme odeslano v ES_APP */
  if (not(new.ES_UID is null) and
      not(new.es_appid is null) and
      (new.es_odeslano is null)
      )
  then
    update ES_APP set odeslano=null where ES_APP.id = new.es_appid;
end

AS
begin
  /* pri presunuti internetove objednavky ji v COSu smazeme */
    if (not(old.idcal_ext is null) and
        not(old.idext is null) and
        ((old.datum <> new.datum) or
         (old.cas <> new.cas) or
         (old.casdo <> new.casdo))
        )
    then begin
      /* zrusit vazbu na COS */
      new.idext = null;
      new.idcal_ext = null;

      /* do smazanych */
      insert into cos_delobj(idext, idcal_ext)
             values(old.idext, old.idcal_ext);
    end
end

AS begin
  NEW.CREATED = 'NOW';
end

as begin
  execute procedure sp_log(old.idpac, 24, old.idobj, 'D', null, null);
end

as begin
  execute procedure sp_log(new.idpac, 24, new.idobj, 'I', null, null);
end

AS
declare variable CELEJMENO varchar(75);
begin
  CELEJMENO = NULL;
  if (new.PRIJMENI is not NULL) then
    CELEJMENO = trim(coalesce(CELEJMENO, '') || ' ' || new.PRIJMENI);
  if (new.JMENO is not NULL) then
    CELEJMENO = trim(coalesce(CELEJMENO, '') || ' ' || new.JMENO);
  if (new.TITUL is not NULL) then
    CELEJMENO = trim(coalesce(CELEJMENO, '') || ' ' || new.TITUL);
  if (CELEJMENO is not NULL) then
    new.CELEJMENO = CELEJMENO;
end

AS
declare variable P integer;
declare variable X integer;
declare variable ID integer;
begin
  /* vygenerovat ctyrmistny PIN unikatni v ramci dne */
  if (new.PIN is NULL) then begin
    P = null;
    ID = null;
    X = 0;
    while ((X<100) and ((P is null) or not(ID is null))) do begin /* max 100 pokusu */
      P = null;
      ID = null;
      select F_ROUND(RAND() * 8999 + 1000, 0) from RDB$DATABASE into :P;
      select first 1 O.IDOBJ from OBJOBJ O where O.PIN=:P and O.DATUM=new.DATUM into :ID;
      X = X + 1;
    end
    new.PIN = P;
  end

  when any do
  begin
    /* smula, nekde je chyba */
  end
end

AS
begin
  POST_EVENT 'OBJOBJ_AIUD';
  POST_EVENT 'OBJOBJ_DELETED';
end

procedures.source:
declare variable tblname varchar(20) character set win1250;
declare variable tblkeyfield varchar(10) character set win1250;
declare variable tblid1keyfield varchar(10) character set win1250;
begin
  if ((akce = 'V') or (exists(select first 1 checked from logset))) then
    begin
      if ((idpac is null) and (rodcis is not null)) then
        select first 1 idpac from kar where rodcis = :rodcis order by vyrazen desc into :idpac;
      insert into log (datum, cas, uzivatel, idpac, tabulka, idrec, akce, detail) values ('now', 'now', user, :idpac, :tabulka, :idrec, :akce, :detail);
    end
  else
    begin
      select nazev, keyfield, id1keyfield from logtables where id = :tabulka into :tblname, :tblkeyfield, :tblid1keyfield;
      if (tblkeyfield is not null) then
        insert into zurnal values (next value for gen_zurnal, 'now', 'now', :tblname, :idrec, user, :akce, :tblkeyfield, :id1, :tblid1keyfield);
    end
end

